-- ── hand-written: what may happen to a payment ──────────────────────────────────────────────────
-- The guard of a payment, whoever writes the row, the functions below included. A payment
-- starts as a draft; once posted it is changed in one way only, by being cancelled as it
-- stands; and only a draft is removed. The times on a row are the database's own. Only a
-- session signed in as postgres itself (a migration, or the removal of a synthetic test
-- company) is not held to this.
CREATE FUNCTION app.check_supplier_payment() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_kept text[] := ARRAY['status', 'cancelled_at', 'cancelled_by', 'cancelled_on', 'cancel_reason', 'updated_at', 'updated_by'];
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.tenant_id IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'a posted payment is never removed' USING ERRCODE = 'SE237';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT isfinite(NEW.payment_date) OR NOT isfinite(coalesce(NEW.cancelled_on, NEW.payment_date)) THEN
    RAISE EXCEPTION 'a date on a payment is a day on the calendar' USING ERRCODE = 'SE242';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'a payment starts as a draft' USING ERRCODE = 'SE236';
    END IF;
    NEW.created_at := now();
    NEW.updated_at := clock_timestamp();
  ELSE
    IF OLD.status = 'cancelled' OR (OLD.status = 'posted' AND NEW.status <> 'cancelled') THEN
      RAISE EXCEPTION 'a posted payment is never changed' USING ERRCODE = 'SE237';
    END IF;
    IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at THEN
      RAISE EXCEPTION 'what a payment is and who wrote it never change' USING ERRCODE = 'SE237';
    END IF;
    -- Cancelling changes nothing else about the payment.
    IF OLD.status = 'posted' AND (to_jsonb(NEW) - v_kept) IS DISTINCT FROM (to_jsonb(OLD) - v_kept) THEN
      RAISE EXCEPTION 'a posted payment is cancelled as it stands' USING ERRCODE = 'SE237';
    END IF;
    -- Always later than what anyone read before this change, so a screen opened earlier can tell.
    NEW.updated_at := clock_timestamp();
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_supplier_payment() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER supplier_payments_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.supplier_payments
  FOR EACH ROW EXECUTE FUNCTION app.check_supplier_payment();
--> statement-breakpoint
ALTER TABLE public.supplier_payments ENABLE ALWAYS TRIGGER supplier_payments_check;
