-- The journal of a payment stands with the payment that names it, and is reversed only when
-- that payment has been cancelled.
CREATE FUNCTION app.journal_backed_supplier_payment(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.supplier_payments p
      WHERE p.tenant_id = p_journal.tenant_id AND p.id = p_journal.source_id AND p.journal_id = p_journal.id AND p.status <> 'draft'
        AND p.number = p_journal.document_number AND p.payment_date = p_journal.journal_date)
  $$;
--> statement-breakpoint
CREATE FUNCTION app.reversal_backed_supplier_payment(p_reversal public.journals, p_original public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.supplier_payments p
      WHERE p.tenant_id = p_original.tenant_id AND p.journal_id = p_original.id AND p.status = 'cancelled' AND p.cancelled_on = p_reversal.journal_date)
  $$;
