-- ── hand-written: what the functions below share ────────────────────────────────────────────────
-- Not for the app to call. A posted payment's row, held for the rest of the transaction, for a
-- member who may pay suppliers; to anyone else, and outside a member's branches, it does not exist.
CREATE FUNCTION app.hold_supplier_payment(p_payment uuid) RETURNS public.supplier_payments
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.supplier_payments%ROWTYPE;
BEGIN
  IF v_tenant IS NULL OR app.current_user_id() IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role cannot pay suppliers' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'purchase documents are written in read committed transactions' USING ERRCODE = 'SE219';
  END IF;
  SELECT d.* INTO v_doc FROM public.supplier_payments d WHERE d.tenant_id = v_tenant AND d.id = p_payment FOR UPDATE;
  IF NOT FOUND OR (v_scope IS NOT NULL AND NOT (v_doc.branch_id = ANY (v_scope))) THEN
    RAISE EXCEPTION 'no such supplier payment in this company' USING ERRCODE = 'SE235';
  END IF;
  -- The supplier is held until the transaction ends: its bills and payments are posted one at
  -- a time, so two cannot settle the same bill past what is owed on it.
  PERFORM 1 FROM public.suppliers s WHERE s.tenant_id = v_tenant AND s.id = v_doc.supplier_id FOR NO KEY UPDATE;
  RETURN v_doc;
END $$;
--> statement-breakpoint
-- What is still owed on a posted bill: what it left owed to the supplier, less what posted
-- payments have settled of it. Null for anything that is not a posted bill of the tenant.
CREATE FUNCTION app.bill_owed(p_tenant uuid, p_bill uuid) RETURNS numeric
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT b.payable - coalesce((
      SELECT sum(a.amount) FROM public.supplier_payment_allocations a
      JOIN public.supplier_payments p ON p.tenant_id = a.tenant_id AND p.id = a.payment_id
      WHERE a.tenant_id = b.tenant_id AND a.bill_id = b.id AND p.status = 'posted'), 0)
    FROM public.supplier_bills b WHERE b.tenant_id = p_tenant AND b.id = p_bill AND b.status = 'posted'
  $$;
--> statement-breakpoint
-- Posts the opposite of one journal on a day, line for line. Returns the reversal.
CREATE FUNCTION app.reverse_payment_journal(p_tenant uuid, p_journal uuid, p_date date, p_memo text) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_original public.journals%ROWTYPE;
  v_reversal uuid;
  v_lines integer;
  v_total numeric;
BEGIN
  SELECT j.* INTO v_original FROM public.journals j WHERE j.tenant_id = p_tenant AND j.id = p_journal;
  IF NOT FOUND OR p_date < v_original.journal_date THEN
    RAISE EXCEPTION 'a payment is taken back on or after the day of everything it posted' USING ERRCODE = 'SE242';
  END IF;
  -- The balance, and the document behind the journal, are asked when the transaction ends, whatever the caller set before this.
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, reverses_journal_id, document_number, memo, branch_id, created_by)
    VALUES (v_original.tenant_id, p_date, 'reversal', v_original.id, v_original.id, NULL, left(p_memo, 500), v_original.branch_id, app.current_user_id())
    RETURNING id INTO v_reversal;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id, supplier_id)
    SELECT l.tenant_id, v_reversal, l.line_no, l.account_id, l.credit, l.debit, l.description, l.customer_id, l.supplier_id
    FROM public.journal_lines l
    WHERE l.tenant_id = v_original.tenant_id AND l.journal_id = v_original.id;
  SELECT count(*), sum(l.debit) INTO v_lines, v_total FROM public.journal_lines l WHERE l.tenant_id = v_original.tenant_id AND l.journal_id = v_reversal;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_original.tenant_id, app.current_user_id(), app.tenant_role(), 'journal.reverse', 'journal', v_reversal,
      jsonb_build_object('date', p_date, 'reverses', v_original.id, 'source', v_original.source_type, 'reversesNumber', v_original.document_number, 'lines', v_lines, 'total', v_total::text));
  RETURN v_reversal;
END $$;
--> statement-breakpoint
-- The cash or bank account money leaves: one that takes entries and is in use.
CREATE FUNCTION app.paying_account(p_tenant uuid, p_account uuid) RETURNS text
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_name text;
BEGIN
  SELECT a.code || ' ' || a.name INTO v_name FROM public.accounts a
    WHERE a.tenant_id = p_tenant AND a.id = p_account AND a.control_type IN ('cash', 'bank') AND NOT a.is_group AND a.archived_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'the money leaves a cash or bank account that is in use' USING ERRCODE = 'SE241';
  END IF;
  RETURN v_name;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.hold_supplier_payment(uuid), app.bill_owed(uuid, uuid), app.reverse_payment_journal(uuid, uuid, date, text), app.paying_account(uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.hold_supplier_payment(uuid), app.bill_owed(uuid, uuid), app.reverse_payment_journal(uuid, uuid, date, text), app.paying_account(uuid, uuid) FROM app_runtime, anon, authenticated, service_role;
