-- ── hand-written: posting a payment ─────────────────────────────────────────────────────────────
-- One act of the database, whole or not at all. The payment takes its PV number; what it
-- settles of each bill is no more than is still owed on that bill, and in all no more than the
-- payment; the rest is an advance. Returns the number.
CREATE FUNCTION app.post_supplier_payment(p_payment uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_doc public.supplier_payments%ROWTYPE := app.hold_supplier_payment(p_payment);
  v_tenant uuid := v_doc.tenant_id;
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_supplier text;
  v_account text;
  v_line record;
  v_settled numeric := 0;
  v_lines integer := 0;
  v_number text;
  v_journal uuid;
  v_no integer := 0;
BEGIN
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft payment is posted' USING ERRCODE = 'SE236';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF v_doc.payment_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE242';
  END IF;
  PERFORM app.require_open_period(v_tenant, v_doc.payment_date);
  v_account := app.paying_account(v_tenant, v_doc.account_id);
  IF v_doc.foreign_currency IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.currencies c WHERE c.tenant_id = v_tenant AND c.code = v_doc.foreign_currency AND NOT c.is_base
  ) THEN
    RAISE EXCEPTION 'a foreign currency is one of the company''s own, other than the one it keeps its books in' USING ERRCODE = 'SE245';
  END IF;
  SELECT s.name INTO v_supplier FROM public.suppliers s WHERE s.tenant_id = v_tenant AND s.id = v_doc.supplier_id;

  FOR v_line IN
    SELECT a.bill_id, a.amount, a.journal_id, b.status AS bill_status, b.supplier_id, b.branch_id, b.bill_date, b.number,
           app.bill_owed(v_tenant, a.bill_id) AS owed,
           count(*) OVER (PARTITION BY a.bill_id) AS times
    FROM public.supplier_payment_allocations a
    LEFT JOIN public.supplier_bills b ON b.tenant_id = a.tenant_id AND b.id = a.bill_id
    WHERE a.tenant_id = v_tenant AND a.payment_id = v_doc.id
    ORDER BY b.bill_date, b.number
  LOOP
    IF v_line.journal_id IS NOT NULL OR v_line.bill_status IS DISTINCT FROM 'posted' OR v_line.supplier_id <> v_doc.supplier_id OR v_line.branch_id <> v_doc.branch_id
       OR v_line.bill_date > v_doc.payment_date THEN
      RAISE EXCEPTION 'a payment settles posted bills of its own supplier and branch, dated on or before it' USING ERRCODE = 'SE238';
    END IF;
    IF v_line.times > 1 THEN
      RAISE EXCEPTION 'bill % is on the payment twice', v_line.number USING ERRCODE = 'SE244';
    END IF;
    IF v_line.amount > v_line.owed THEN
      RAISE EXCEPTION 'more set against bill % than is still owed on it: % owed, % on this payment', v_line.number, v_line.owed, v_line.amount USING ERRCODE = 'SE239';
    END IF;
    v_settled := v_settled + v_line.amount;
    v_lines := v_lines + 1;
  END LOOP;
  IF v_settled > v_doc.amount THEN
    RAISE EXCEPTION 'more set against bills than the payment: % against %', v_settled, v_doc.amount USING ERRCODE = 'SE240';
  END IF;

  v_number := app.next_document_number('PV', v_doc.payment_date);
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
    VALUES (v_tenant, v_doc.payment_date, 'supplier_payment', v_doc.id, v_number, left('Paid to ' || v_supplier, 500), v_doc.branch_id, v_user)
    RETURNING id INTO v_journal;
  IF v_settled > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, supplier_id)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'ap'), v_settled, 0, 'Bills paid', v_doc.supplier_id);
  END IF;
  IF v_doc.amount - v_settled > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, supplier_id)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'supplier_advances'), v_doc.amount - v_settled, 0, 'Paid in advance', v_doc.supplier_id);
  END IF;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
    VALUES (v_tenant, v_journal, v_no + 1, v_doc.account_id, 0, v_doc.amount, 'Paid to ' || v_supplier);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', v_doc.payment_date, 'source', 'supplier_payment', 'sourceId', v_doc.id, 'number', v_number, 'lines', v_no + 1, 'total', v_doc.amount::text));
  UPDATE public.supplier_payments d SET status = 'posted', number = v_number, journal_id = v_journal, posted_at = now(), posted_by = v_user, updated_by = v_user
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'supplier_payment.post', 'supplier_payment', v_doc.id,
      jsonb_build_object('number', v_number, 'supplier', v_supplier, 'date', v_doc.payment_date, 'account', v_account, 'amount', v_doc.amount::text,
        'settled', v_settled::text, 'advance', (v_doc.amount - v_settled)::text, 'bills', v_lines,
        'foreign', CASE WHEN v_doc.foreign_currency IS NULL THEN NULL ELSE v_doc.foreign_currency || ' ' || v_doc.foreign_amount::text END, 'journalId', v_journal));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.post_supplier_payment(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.post_supplier_payment(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: setting an advance against bills ──────────────────────────────────────────────
-- What is left of a posted payment (its advance) is set against posted bills of the same
-- supplier and branch, on a day on or after the payment and each bill: debit Trade payables,
-- credit Advances to suppliers. p_allocations is a list of {"bill_id", "amount"}. Returns how
-- many bills it was set against.
CREATE FUNCTION app.apply_supplier_advance(p_payment uuid, p_date date, p_allocations jsonb) RETURNS integer
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_doc public.supplier_payments%ROWTYPE := app.hold_supplier_payment(p_payment);
  v_tenant uuid := v_doc.tenant_id;
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_supplier text;
  v_left numeric;
  v_line record;
  v_total numeric := 0;
  v_lines integer := 0;
  v_journal uuid;
BEGIN
  IF v_doc.status <> 'posted' THEN
    RAISE EXCEPTION 'an advance is set against a bill from a posted payment' USING ERRCODE = 'SE236';
  END IF;
  IF p_date IS NULL OR NOT isfinite(p_date) OR p_date < v_doc.payment_date OR p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'an advance is set against a bill on a day that has come, on or after the payment' USING ERRCODE = 'SE242';
  END IF;
  IF p_allocations IS NULL OR jsonb_typeof(p_allocations) <> 'array' OR jsonb_array_length(p_allocations) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'name between 1 and 200 bills to set the advance against' USING ERRCODE = 'SE244';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);
  SELECT s.name INTO v_supplier FROM public.suppliers s WHERE s.tenant_id = v_tenant AND s.id = v_doc.supplier_id;
  v_left := v_doc.amount - coalesce((SELECT sum(a.amount) FROM public.supplier_payment_allocations a WHERE a.tenant_id = v_tenant AND a.payment_id = v_doc.id), 0);

  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
    VALUES (v_tenant, p_date, 'supplier_advance_application', v_doc.id, v_doc.number, left('Advance to ' || v_supplier || ' set against bills', 500), v_doc.branch_id, v_user)
    RETURNING id INTO v_journal;
  FOR v_line IN
    SELECT (x.value->>'bill_id')::uuid AS bill_id, (x.value->>'amount')::numeric AS amount, b.status AS bill_status, b.supplier_id, b.branch_id, b.bill_date, b.number,
           count(*) OVER (PARTITION BY x.value->>'bill_id') AS times
    FROM jsonb_array_elements(p_allocations) AS x(value)
    LEFT JOIN public.supplier_bills b ON b.tenant_id = v_tenant AND b.id = (x.value->>'bill_id')::uuid
    ORDER BY b.bill_date, b.number
  LOOP
    IF v_line.bill_status IS DISTINCT FROM 'posted' OR v_line.supplier_id <> v_doc.supplier_id OR v_line.branch_id <> v_doc.branch_id OR v_line.bill_date > p_date THEN
      RAISE EXCEPTION 'a payment settles posted bills of its own supplier and branch, dated on or before it' USING ERRCODE = 'SE238';
    END IF;
    IF v_line.times > 1 THEN
      RAISE EXCEPTION 'bill % is named twice', v_line.number USING ERRCODE = 'SE244';
    END IF;
    -- "Not a number" passes "> 0"; the upper bound refuses it. An amount is to the paisa.
    IF v_line.amount IS NULL OR NOT (v_line.amount > 0 AND v_line.amount < 1e16) OR v_line.amount <> round(v_line.amount, 2) THEN
      RAISE EXCEPTION 'an amount set against a bill is more than nothing, to the paisa' USING ERRCODE = 'SE244';
    END IF;
    IF v_line.amount > app.bill_owed(v_tenant, v_line.bill_id) THEN
      RAISE EXCEPTION 'more set against bill % than is still owed on it', v_line.number USING ERRCODE = 'SE239';
    END IF;
    INSERT INTO public.supplier_payment_allocations (tenant_id, payment_id, bill_id, amount, applied_on, journal_id, created_by)
      VALUES (v_tenant, v_doc.id, v_line.bill_id, v_line.amount, p_date, v_journal, v_user);
    v_total := v_total + v_line.amount;
    v_lines := v_lines + 1;
  END LOOP;
  IF v_total > v_left THEN
    RAISE EXCEPTION 'more set against bills than is left of the advance: % against %', v_total, v_left USING ERRCODE = 'SE240';
  END IF;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, supplier_id)
    VALUES (v_tenant, v_journal, 1, app.control_account(v_tenant, 'ap'), v_total, 0, 'Advance set against bills', v_doc.supplier_id),
           (v_tenant, v_journal, 2, app.control_account(v_tenant, 'supplier_advances'), 0, v_total, 'Advance ' || v_doc.number || ' set against bills', v_doc.supplier_id);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_date, 'source', 'supplier_advance_application', 'sourceId', v_doc.id, 'number', v_doc.number, 'lines', 2, 'total', v_total::text));
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'supplier_payment.apply_advance', 'supplier_payment', v_doc.id,
      jsonb_build_object('number', v_doc.number, 'supplier', v_supplier, 'date', p_date, 'amount', v_total::text, 'bills', v_lines, 'left', (v_left - v_total)::text, 'journalId', v_journal));
  RETURN v_lines;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.apply_supplier_advance(uuid, date, jsonb) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.apply_supplier_advance(uuid, date, jsonb) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: cancelling a payment ──────────────────────────────────────────────────────────
-- A payment entered by mistake is taken back as it stands, on a day on or after everything it
-- posted, with a reason: the opposite of its journal, and of every journal that set its
-- advance against a bill, is posted. Its bills are owed again. It keeps its number.
CREATE FUNCTION app.cancel_supplier_payment(p_payment uuid, p_date date, p_reason text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_doc public.supplier_payments%ROWTYPE := app.hold_supplier_payment(p_payment);
  v_tenant uuid := v_doc.tenant_id;
  v_user uuid := app.current_user_id();
  v_reason text := nullif(btrim(p_reason), '');
  v_journal uuid;
  v_reversed integer := 0;
BEGIN
  IF v_doc.status <> 'posted' THEN
    RAISE EXCEPTION 'only a posted payment is cancelled' USING ERRCODE = 'SE236';
  END IF;
  IF v_reason IS NULL OR char_length(v_reason) NOT BETWEEN 3 AND 300 THEN
    RAISE EXCEPTION 'a payment is cancelled with a reason of 3 to 300 characters' USING ERRCODE = 'SE236';
  END IF;
  IF p_date IS NULL OR NOT isfinite(p_date) OR p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE242';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);
  -- Cancelled first: each reversal asks that its payment is.
  UPDATE public.supplier_payments d SET status = 'cancelled', cancelled_at = now(), cancelled_by = v_user, cancelled_on = p_date, cancel_reason = v_reason, updated_by = v_user
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id;
  FOR v_journal IN
    SELECT v_doc.journal_id
    UNION
    SELECT a.journal_id FROM public.supplier_payment_allocations a WHERE a.tenant_id = v_tenant AND a.payment_id = v_doc.id AND a.journal_id IS NOT NULL
  LOOP
    PERFORM app.reverse_payment_journal(v_tenant, v_journal, p_date, 'Payment ' || v_doc.number || ' cancelled: ' || v_reason);
    v_reversed := v_reversed + 1;
  END LOOP;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, app.tenant_role(), 'supplier_payment.cancel', 'supplier_payment', v_doc.id,
      jsonb_build_object('number', v_doc.number, 'date', p_date, 'reason', v_reason, 'amount', v_doc.amount::text, 'journalsReversed', v_reversed));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cancel_supplier_payment(uuid, date, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.cancel_supplier_payment(uuid, date, text) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: recording a challan ───────────────────────────────────────────────────────────
-- Tax withheld from suppliers, paid to the government out of a cash or bank account: debit the
-- withholding payable account of that kind, credit the account. A challan pays whole
-- withholding entries of its own kind, each once; its amount is theirs. It belongs to the
-- whole company, so only a member who works in every branch records one. Returns its number.
CREATE FUNCTION app.record_withholding_challan(p_kind text, p_paid_on date, p_account uuid, p_challan_no text, p_entries uuid[], p_note text DEFAULT NULL) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_control text;
  v_account text;
  v_challan_no text := nullif(btrim(p_challan_no), '');
  v_count integer;
  v_amount numeric;
  v_id uuid := gen_random_uuid();
  v_number text;
  v_journal uuid;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') OR app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'this member cannot record a challan' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'purchase documents are written in read committed transactions' USING ERRCODE = 'SE219';
  END IF;
  v_control := CASE p_kind WHEN 'income_tax' THEN 'wht_income_tax' WHEN 'sales_tax' THEN 'wht_sales_tax' WHEN 'provincial_sales_tax' THEN 'wht_provincial_tax' END;
  IF v_control IS NULL OR v_challan_no IS NULL OR char_length(v_challan_no) > 60 OR p_entries IS NULL OR cardinality(p_entries) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'a challan is of one kind of tax, has a number, and pays between 1 and 500 withholding entries' USING ERRCODE = 'SE243';
  END IF;
  IF p_paid_on IS NULL OR NOT isfinite(p_paid_on) OR p_paid_on > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE242';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_paid_on);
  v_account := app.paying_account(v_tenant, p_account);
  -- The entries are held, in one order, so that two challans cannot pay the same one.
  PERFORM 1 FROM public.withholding_entries e WHERE e.tenant_id = v_tenant AND e.id = ANY (p_entries) ORDER BY e.id FOR UPDATE;
  SELECT count(*), sum(e.amount) INTO v_count, v_amount FROM public.withholding_entries e
    WHERE e.tenant_id = v_tenant AND e.id = ANY (p_entries) AND e.kind = p_kind AND e.entry_date <= p_paid_on
      AND NOT EXISTS (SELECT 1 FROM public.withholding_challan_entries c WHERE c.tenant_id = e.tenant_id AND c.entry_id = e.id);
  IF v_count <> cardinality(p_entries) OR v_count <> (SELECT count(DISTINCT x) FROM unnest(p_entries) AS x) THEN
    RAISE EXCEPTION 'a challan pays whole withholding entries of its own kind, withheld on or before its date, each once' USING ERRCODE = 'SE243';
  END IF;

  v_number := app.next_document_number('WC', p_paid_on);
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
    VALUES (v_tenant, p_paid_on, 'withholding_challan', v_id, v_number, left('Tax withheld paid under challan ' || v_challan_no, 500), NULL, v_user)
    RETURNING id INTO v_journal;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
    VALUES (v_tenant, v_journal, 1, app.control_account(v_tenant, v_control), v_amount, 0, 'Challan ' || v_challan_no),
           (v_tenant, v_journal, 2, p_account, 0, v_amount, 'Challan ' || v_challan_no);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_paid_on, 'source', 'withholding_challan', 'sourceId', v_id, 'number', v_number, 'lines', 2, 'total', v_amount::text));
  INSERT INTO public.withholding_challans (id, tenant_id, number, kind, challan_no, paid_on, account_id, amount, note, journal_id, created_by)
    VALUES (v_id, v_tenant, v_number, p_kind, v_challan_no, p_paid_on, p_account, v_amount, nullif(btrim(p_note), ''), v_journal, v_user);
  INSERT INTO public.withholding_challan_entries (tenant_id, challan_id, entry_id)
    SELECT v_tenant, v_id, x FROM unnest(p_entries) AS x;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'withholding_challan.record', 'withholding_challan', v_id,
      jsonb_build_object('number', v_number, 'kind', p_kind, 'challan', v_challan_no, 'date', p_paid_on, 'account', v_account, 'amount', v_amount::text, 'entries', v_count, 'journalId', v_journal));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.record_withholding_challan(text, date, uuid, text, uuid[], text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.record_withholding_challan(text, date, uuid, text, uuid[], text) TO app_runtime;
